1	//! Standalone, executable regression target for strict configuration
2	//! definitions and strict port value interpretation in a layered
3	//! plugin-dispatch CLI.
4	//!
5	//! Unlike the tests under `tests/derive/`, this file is a self-contained test
6	//! target that defines its own derived CLI and observes every result solely
7	//! through the public `clap::Parser` API via `Cli::try_parse_from` (argv0
8	//! included): successful structures, typed errors, and rendered help text.
9	//! Every case reports the actual tokens it ran with together with the
10	//! observed defines, port, error kind and triggering token, rather than only
11	//! contributing to an aggregate pass/fail.
12	//!
13	//! Scenario under test:
14	//! * root command `tool` with a global default config path and a root-level
15	//!   repeatable `--define` that accepts only exactly one non-empty key, one
16	//!   non-empty value and exactly one `=` separator, with no whitespace on
17	//!   either side of the pair;
18	//! * declared subcommands `serve` and `check`, plus a root external
19	//!   catch-all; `serve` declares `worker` and has its own external catch-all;
20	//! * `--define` is *not* global: it parses only while the root command is
21	//!   active, keeps occurrence order, is rejected with the triggering token at
22	//!   any deeper level, and is never parsed once either external capture
23	//!   starts;
24	//! * `worker` requires a unique `--port` built only from ASCII decimal digits
25	//!   in 1..=65535: empty strings, sign prefixes, hex, underscores, embedded
26	//!   whitespace and overflowing values are all reported as invalid values
27	//!   instead of being normalized, truncated or accepted;
28	//! * missing port, duplicate port, protocol conflicts and invalid values keep
29	//!   distinguishable error kinds that name the most specific command, while
30	//!   `check` and the plugin paths never inherit the port constraint;
31	//! * a fixed sequence of define success, every invalid-define class, port
32	//!   negatives, external success, a valid worker after a failure and
33	//!   four-level help is mutually isolated: help succeeds while required
34	//!   values are missing, carries no stale error, reflects only its own input,
35	//!   and keeps a stable ordering.
36	#![cfg(feature = "derive")]
37	#![cfg(feature = "help")]
38	#![cfg(feature = "usage")]
39	
40	use clap::Args;
41	use clap::Parser;
42	use clap::Subcommand;
43	use clap::error::ErrorKind;
44	
45	/// Strict `key=value` parser for root-level definitions.
46	///
47	/// Exactly one `=` separator, a non-empty key, a non-empty value and no
48	/// whitespace on either side of the pair. Empty keys, empty values, leading
49	/// or trailing `=`, additional `=` and whitespace around the pair are all
50	/// rejected instead of being trimmed, split further or silently accepted.
51	fn parse_define(raw: &str) -> Result<(String, String), String> {
52	    let Some((key, value)) = raw.split_once('=') else {
53	        return Err(format!("invalid define `{raw}`: expected key=value"));
54	    };
55	    if value.contains('=') {
56	        return Err(format!(
57	            "invalid define `{raw}`: expected exactly one `=` in key=value"
58	        ));
59	    }
60	    if key.is_empty() {
61	        return Err(format!("invalid define `{raw}`: key must not be empty"));
62	    }
63	    if value.is_empty() {
64	        return Err(format!("invalid define `{raw}`: value must not be empty"));
65	    }
66	    if key.chars().any(char::is_whitespace) || value.chars().any(char::is_whitespace) {
67	        return Err(format!(
68	            "invalid define `{raw}`: key and value must not contain whitespace"
69	        ));
70	    }
71	    Ok((key.to_owned(), value.to_owned()))
72	}
