74	/// Strict decimal port parser: ASCII digits only, range 1..=65535.
75	///
76	/// Signs, hex prefixes, underscores, whitespace and empty values are all
77	/// rejected instead of being normalized, truncated or wrapped by a lenient
78	/// integer conversion.
79	fn parse_port(raw: &str) -> Result<u16, String> {
80	    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
81	        return Err(format!(
82	            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
83	        ));
84	    }
85	    match raw.parse::<u32>() {
86	        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
87	        _ => Err(format!(
88	            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
89	        )),
90	    }
91	}
