93	#[derive(Parser, Debug, Clone, PartialEq)]
94	#[command(
95	    name = "tool",
96	    after_help = "External plugins: any other <COMMAND> is captured as a root plugin."
97	)]
98	struct Cli {
99	    #[arg(
100	        long,
101	        global = true,
102	        default_value = "builtin.toml",
103	        value_name = "path"
104	    )]
105	    config: String,
106	    #[arg(long, value_name = "key=value", value_parser = parse_define)]
107	    define: Vec<(String, String)>,
108	    #[command(subcommand)]
109	    command: Commands,
110	}
111	
112	#[derive(Subcommand, Debug, Clone, PartialEq)]
113	enum Commands {
114	    Serve(ServeArgs),
115	    Check(CheckArgs),
116	    #[command(external_subcommand)]
117	    External(Vec<String>),
118	}
119	
120	#[derive(Args, Debug, Clone, PartialEq)]
121	#[command(after_help = "External plugins: any other <COMMAND> is captured as a serve plugin.")]
122	struct ServeArgs {
123	    #[command(subcommand)]
124	    command: ServeCommands,
125	}
126	
127	#[derive(Subcommand, Debug, Clone, PartialEq)]
128	enum ServeCommands {
129	    Worker(WorkerArgs),
130	    #[command(external_subcommand)]
131	    External(Vec<String>),
132	}
