134	#[derive(Args, Debug, Clone, PartialEq)]
135	struct WorkerArgs {
136	    #[arg(long, value_name = "port", required = true, value_parser = parse_port)]
137	    port: u16,
138	    #[arg(long, conflicts_with = "udp")]
139	    tcp: bool,
140	    #[arg(long, conflicts_with = "tcp")]
141	    udp: bool,
142	    #[arg(last = true)]
143	    trailing: Vec<String>,
144	}
