146	#[derive(Args, Debug, Clone, PartialEq)]
147	struct CheckArgs {
148	    path: Option<String>,
149	    #[arg(long)]
150	    strict: bool,
151	}
152	
153	fn parse(argv: &[&str]) -> Result<Cli, clap::Error> {
154	    Cli::try_parse_from(argv)
155	}
