157	fn root_external_ok(argv: &[&str]) -> (String, Vec<(String, String)>, Vec<String>) {
158	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
159	    let Commands::External(tokens) = &cli.command else {
160	        panic!(
161	            "expected root external subcommand for {argv:?}, got {:?}",
162	            cli.command
163	        );
164	    };
165	    assert!(
166	        !tokens.is_empty(),
167	        "external capture must always include the command name: {argv:?}"
168	    );
169	    eprintln!(
170	        "{argv:?} => root plugin: config={:?} define={:?} tokens={:?}",
171	        cli.config, cli.define, tokens
172	    );
173	    (cli.config, cli.define, tokens.clone())
174	}
175	
176	fn serve_external_ok(argv: &[&str]) -> (String, Vec<(String, String)>, Vec<String>) {
177	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
178	    let Commands::Serve(serve) = &cli.command else {
179	        panic!("expected `serve` for {argv:?}, got {:?}", cli.command);
180	    };
181	    let ServeCommands::External(tokens) = &serve.command else {
182	        panic!(
183	            "expected serve external subcommand for {argv:?}, got {:?}",
184	            serve.command
185	        );
186	    };
187	    assert!(
188	        !tokens.is_empty(),
189	        "external capture must always include the command name: {argv:?}"
190	    );
191	    eprintln!(
192	        "{argv:?} => serve plugin: config={:?} define={:?} tokens={:?}",
193	        cli.config, cli.define, tokens
194	    );
195	    (cli.config, cli.define, tokens.clone())
196	}
