198	fn worker_ok(argv: &[&str]) -> (String, Vec<(String, String)>, WorkerArgs) {
199	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
200	    let Commands::Serve(serve) = &cli.command else {
201	        panic!(
202	            "expected `serve worker` for {argv:?}, got {:?}",
203	            cli.command
204	        );
205	    };
206	    let ServeCommands::Worker(worker) = &serve.command else {
207	        panic!("expected `worker` for {argv:?}, got {:?}", serve.command);
208	    };
209	    eprintln!(
210	        "{argv:?} => worker: config={:?} define={:?} port={} tcp={} udp={} trailing={:?}",
211	        cli.config, cli.define, worker.port, worker.tcp, worker.udp, worker.trailing
212	    );
213	    (cli.config, cli.define, worker.clone())
214	}
