216	fn check_ok(argv: &[&str]) -> (String, Vec<(String, String)>, CheckArgs) {
217	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
218	    let Commands::Check(check) = &cli.command else {
219	        panic!("expected `check` for {argv:?}, got {:?}", cli.command);
220	    };
221	    eprintln!(
222	        "{argv:?} => check: config={:?} define={:?} path={:?} strict={}",
223	        cli.config, cli.define, check.path, check.strict
