228	/// Render an error while dropping the optional backtrace appended by clap's
229	/// `debug` feature. The backtrace captures host paths and frame line numbers
230	/// and is not part of the user-facing help or error output under test.
231	fn rendered(err: &clap::Error) -> String {
232	    let text = err.to_string();
233	    match text.split_once("\nBacktrace:") {
234	        Some((head, _)) => head.trim_end().to_owned(),
235	        None => text,
236	    }
237	}
238	
239	fn fail_kind(argv: &[&str]) -> (ErrorKind, String) {
240	    match parse(argv) {
241	        // A failure case that parses would leave a partially populated match
242	        // readable; the acceptance contract forbids that.
243	        Ok(cli) => panic!("expected failure for {argv:?}, got {cli:?}"),
244	        Err(err) => {
245	            let kind = err.kind();
246	            let msg = rendered(&err);
247	            let first_line = msg.lines().next().unwrap_or_default().to_owned();
248	            eprintln!("{argv:?} => error kind={kind:?}: {first_line}");
249	            (kind, msg)
250	        }
251	    }
252	}
253	
254	fn help_text(argv: &[&str]) -> String {
255	    let err = parse(argv).expect_err("help is reported as a DisplayHelp error");
256	    assert_eq!(err.kind(), ErrorKind::DisplayHelp, "{argv:?}");
257	    let help = rendered(&err);
258	    eprintln!("{argv:?} => help ({} bytes)", help.len());
259	    help
260	}
