264	#[test]
265	fn defines_keep_occurrence_order_and_split_into_pairs() {
266	    let (config, define, worker) = worker_ok(&[
267	        "tool",
268	        "--define",
269	        "a=1",
270	        "--define",
271	        "b=two",
272	        "--define=c=3",
273	        "serve",
274	        "worker",
275	        "--port",
276	        "8080",
277	    ]);
278	    assert_eq!(config, "builtin.toml");
