290	#[test]
291	fn define_pairs_keep_inner_punctuation_verbatim() {
292	    // Punctuation that is neither `=` nor whitespace is part of the data and
293	    // is never trimmed or reinterpreted.
294	    let (_, define, _) = worker_ok(&[
295	        "tool",
296	        "--define",
297	        "a.b-c_d=e/f:1",
298	        "--define",
299	        "x=y,z;w",
300	        "--define",
