302	        "serve",
303	        "worker",
304	        "--port",
305	        "80",
306	    ]);
307	    assert_eq!(
308	        define,
309	        vec![
310	            ("a.b-c_d".to_owned(), "e/f:1".to_owned()),
311	            ("x".to_owned(), "y,z;w".to_owned()),
312	            ("1".to_owned(), "2".to_owned()),
313	        ]
