317	#[test]
318	fn defines_parse_only_until_any_external_capture_starts() {
319	    // Root capture: defines before the name parse, everything after is data.
320	    let (_, define, tokens) = root_external_ok(&["tool", "--define", "k=v", "plug", "--define", "x=y"]);
321	    assert_eq!(define, vec![("k".to_owned(), "v".to_owned())]);
322	    assert_eq!(tokens, vec!["plug", "--define", "x=y"]);
323	
324	    // Serve capture: a define between `serve` and the plugin name would be a
325	    // serve-level token and is covered by the wrong-level failures; once the
326	    // serve plugin name is selected, define-like tokens are plugin data.
327	    let (_, define, tokens) =
328	        serve_external_ok(&["tool", "--define", "k=v", "serve", "plug", "--define", "x=y"]);
329	    assert_eq!(define, vec![("k".to_owned(), "v".to_owned())]);
330	    assert_eq!(tokens, vec!["plug", "--define", "x=y"]);
331	}
