333	// ---- invalid defines: one case per rejected class -------------------------
334	
335	/// Every class of malformed definition, with the exact token under test.
336	const INVALID_DEFINES: &[&str] = &[
337	    "",        // empty string
338	    "=",       // only a separator: empty key and empty value
339	    "=v",      // leading equals: empty key
340	    "k=",      // trailing equals: empty value
341	    "a=b=c",   // more than one separator
342	    "novalue", // no separator at all
343	    " a=b",    // whitespace before the key
344	    "a =b",    // whitespace after the key
345	    "a= b",    // whitespace before the value
346	    "a=b ",    // whitespace after the value
347	    "a b=c",   // whitespace inside the key
348	    "a=b c",   // whitespace inside the value
349	];
350	
351	#[test]
352	fn every_invalid_define_class_is_a_value_validation_error() {
353	    for raw in INVALID_DEFINES {
354	        for argv in [
355	            vec!["tool", "--define", raw, "serve", "worker", "--port", "80"],
356	            vec![
357	                "tool",
358	                format!("--define={raw}").as_str(),
359	                "serve",
360	                "worker",
361	                "--port",
362	                "80",
363	            ],
364	        ] {
365	            let (kind, msg) = fail_kind(&argv);
366	            assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
367	            assert!(msg.contains("--define"), "{argv:?}: {msg}");
368	            // The offending value is attributed verbatim, even when empty.
369	            assert!(msg.contains(&format!("'{raw}'")), "{argv:?}: {msg}");
370	        }
371	    }
372	}
