374	#[test]
375	fn invalid_define_never_leaves_a_partial_match_at_any_level() {
376	    // The failure is attributed to `--define` and its value even when every
377	    // later token would have been valid on its own; no partial structure
378	    // (the check path, the strict flag) is readable from the result.
379	    let (kind, msg) = fail_kind(&["tool", "--define", "=v", "check", "path", "--strict"]);
380	    assert_eq!(kind, ErrorKind::ValueValidation);
381	    assert!(msg.contains("--define"), "{msg}");
382	    assert!(msg.contains("'=v'"), "{msg}");
383	}
