409	#[test]
410	fn define_below_the_root_is_an_unknown_argument_naming_the_token() {
411	    let cases: &[(&[&str], &str)] = &[
412	        (
413	            &["tool", "serve", "--define", "a=1", "worker", "--port", "80"],
414	            "tool serve",
415	        ),
416	        (
417	            &["tool", "serve", "worker", "--port", "80", "--define", "a=1"],
418	            "tool serve worker",
419	        ),
420	        (&["tool", "check", "--define", "a=1"], "tool check"),
421	        // Even with a plugin name available, a serve-level define fails
422	        // instead of being captured as plugin data.
423	        (&["tool", "serve", "--define", "a=1", "plug"], "tool serve"),
424	    ];
425	    for (argv, usage) in cases {
426	        let (kind, msg) = fail_kind(argv);
427	        assert_eq!(kind, ErrorKind::UnknownArgument, "{argv:?}");
428	        assert!(msg.contains("--define"), "{argv:?}: {msg}");
429	        assert!(msg.contains(usage), "{argv:?}: {msg}");
430	    }
431	}
