433	// ---- port: strict decimal interpretation ----------------------------------
434	
435	#[test]
436	fn port_accepts_decimal_bounds_only() {
437	    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port", "1"]);
438	    assert_eq!(worker.port, 1);
439	    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port=65535"]);
440	    assert_eq!(worker.port, 65535);
441	    // Leading zeroes are still plain decimal digits.
442	    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port", "080"]);
443	    assert_eq!(worker.port, 80);
444	}
