446	#[test]
447	fn every_non_decimal_or_out_of_range_port_is_an_invalid_value() {
448	    // Attached form: every token reaches the port parser as its value.
449	    for bad in [
450	        "",                    // empty string
451	        "-1",                  // negative sign prefix
452	        "+80",                 // plus sign prefix
453	        "0x10",                // hexadecimal
454	        "1_000",               // digit separator
455	        " 80",                 // leading whitespace
456	        "80 ",                 // trailing whitespace
457	        "8 0",                 // embedded whitespace
458	        "abc",                 // non-numeric
459	        "0",                   // below the range
460	        "65536",               // above the range
461	        "99999999999999999999", // overflows any machine integer
462	    ] {
463	        let argv = ["tool", "serve", "worker", &format!("--port={bad}")];
464	        let (kind, msg) = fail_kind(&argv);
465	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
466	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
467	        // The offending value is attributed verbatim, even when empty.
468	        assert!(msg.contains(&format!("'{bad}'")), "{argv:?}: {msg}");
469	    }
470	
471	    // Detached form: tokens that do not look like flags are consumed as the
472	    // value and rejected by the same parser, never loosely converted.
473	    for bad in ["", "+80", "0x10", "1_000", " 80", "80 ", "abc", "0", "65536"] {
474	        let argv = ["tool", "serve", "worker", "--port", bad];
475	        let (kind, msg) = fail_kind(&argv);
476	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
477	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
478	    }
479	
480	    // A detached negative number is consumed by the option lexer as a flag
481	    // and is therefore reported as the unknown token it actually is; it is
482	    // still rejected, never accepted or truncated.
483	    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "-1"]);
484	    assert_eq!(kind, ErrorKind::UnknownArgument);
485	    assert!(msg.contains("-1"), "{msg}");
486	    assert!(msg.contains("tool serve worker"), "{msg}");
487	}
