489	#[test]
490	fn missing_duplicate_and_conflicting_port_arguments_keep_distinct_kinds() {
491	    let (kind, msg) = fail_kind(&["tool", "serve", "worker"]);
492	    assert_eq!(kind, ErrorKind::MissingRequiredArgument);
493	    assert!(msg.contains("--port"), "{msg}");
494	    assert!(msg.contains("tool serve worker"), "{msg}");
495	    assert!(!msg.contains("tool check"), "{msg}");
496	
497	    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "80", "--port", "90"]);
498	    assert_eq!(kind, ErrorKind::ArgumentConflict);
499	    assert!(msg.contains("--port"), "{msg}");
500	    assert!(msg.contains("tool serve worker"), "{msg}");
501	
502	    let (kind, msg) =
503	        fail_kind(&["tool", "serve", "worker", "--port", "80", "--tcp", "--udp"]);
504	    assert_eq!(kind, ErrorKind::ArgumentConflict);
505	    assert!(msg.contains("--tcp"), "{msg}");
506	    assert!(msg.contains("--udp"), "{msg}");
507	    assert!(msg.contains("tool serve worker"), "{msg}");
508	
509	    // The three categories stay distinguishable from each other and from an
510	    // invalid value.
511	    let (invalid, _) = fail_kind(&["tool", "serve", "worker", "--port", "0"]);
512	    assert_eq!(invalid, ErrorKind::ValueValidation);
513	    assert_ne!(ErrorKind::MissingRequiredArgument, ErrorKind::ArgumentConflict);
514	    assert_ne!(ErrorKind::MissingRequiredArgument, invalid);
515	    assert_ne!(ErrorKind::ArgumentConflict, invalid);
516	}
