518	#[test]
519	fn check_and_plugin_paths_do_not_inherit_the_port_constraint() {
520	    // Numeric-looking paths are plain data for `check`.
521	    let (_, _, check) = check_ok(&["tool", "check", "65536"]);
522	    assert_eq!(check.path.as_deref(), Some("65536"));
523	
524	    // The port option itself is unknown to `check`, not reinterpreted.
525	    let (kind, msg) = fail_kind(&["tool", "check", "--port", "80"]);
526	    assert_eq!(kind, ErrorKind::UnknownArgument);
527	    assert!(msg.contains("--port"), "{msg}");
528	    assert!(msg.contains("tool check"), "{msg}");
529	    assert!(!msg.contains("tool serve worker"), "{msg}");
530	
531	    // Plugin captures pass port-shaped tokens through verbatim.
532	    let (_, define, tokens) = root_external_ok(&["tool", "plug", "--port", "0", "--define", "bad"]);
533	    assert_eq!(define, Vec::<(String, String)>::new());
534	    assert_eq!(tokens, vec!["plug", "--port", "0", "--define", "bad"]);
535	
536	    let (_, define, tokens) = serve_external_ok(&["tool", "serve", "plug", "--port", "abc"]);
537	    assert_eq!(define, Vec::<(String, String)>::new());
538	    assert_eq!(tokens, vec!["plug", "--port", "abc"]);
539	}
