543	#[test]
544	fn external_captures_keep_every_token_after_the_name_verbatim() {
545	    let (config, define, tokens) = root_external_ok(&[
546	        "tool",
547	        "--define",
548	        "a=1",
549	        "--config",
550	        "custom.toml",
551	        "plug",
552	        "--config",
553	        "stolen.toml",
554	        "--define",
555	        "=v",
556	        "serve",
557	        "worker",
558	        "--",
559	        "",
560	    ]);
561	    assert_eq!(config, "custom.toml");
562	    assert_eq!(define, vec![("a".to_owned(), "1".to_owned())]);
563	    assert_eq!(
564	        tokens,
565	        vec![
566	            "plug",
567	            "--config",
568	            "stolen.toml",
569	            "--define",
570	            "=v",
571	            "serve",
572	            "worker",
573	            "--",
574	            "",
575	        ]
576	    );
577	
578	    let (config, define, tokens) = serve_external_ok(&[
579	        "tool",
580	        "--define",
581	        "b=2",
582	        "serve",
583	        "plug",
584	        "worker",
585	        "--port",
586	        "0",
587	        "check",
588	    ]);
589	    assert_eq!(config, "builtin.toml");
590	    assert_eq!(define, vec![("b".to_owned(), "2".to_owned())]);
591	    assert_eq!(tokens, vec!["plug", "worker", "--port", "0", "check"]);
592	}
593	
594	// ---- global config position compatibility ---------------------------------
595	
596	#[test]
597	fn global_config_parses_at_any_position_without_changing_the_structure() {
598	    let pairs: &[(&[&str], &[&str])] = &[
599	        (
600	            &["tool", "--config", "c.toml", "serve", "worker", "--port", "80"],
601	            &["tool", "serve", "worker", "--port", "80", "--config", "c.toml"],
602	        ),
603	        (
604	            &["tool", "--config", "c.toml", "check", "p", "--strict"],
605	            &["tool", "check", "p", "--strict", "--config", "c.toml"],
606	        ),
607	    ];
608	    for (left, right) in pairs {
609	        let a = parse(left).unwrap_or_else(|err| panic!("left failed {left:?}: {err}"));
610	        let b = parse(right).unwrap_or_else(|err| panic!("right failed {right:?}: {err}"));
611	        assert_eq!(a, b, "structure differs for {left:?} vs {right:?}");
612	    }
613	
614	    // After an external name, `--config` is plugin data, not a global.
615	    let (config, _, tokens) = root_external_ok(&["tool", "--config", "c.toml", "plug", "--config", "x"]);
616	    assert_eq!(config, "c.toml");
617	    assert_eq!(tokens, vec!["plug", "--config", "x"]);
618	
619	    // Duplicated global config is still a conflict at the level where the
620	    // second occurrence appears.
621	    let (kind, msg) = fail_kind(&[
622	        "tool", "serve", "worker", "--port", "80", "--config", "a", "--config", "b",
623	    ]);
624	    assert_eq!(kind, ErrorKind::ArgumentConflict);
625	    assert!(msg.contains("--config"), "{msg}");
626	    assert!(msg.contains("tool serve worker"), "{msg}");
627	}
628	
629	// ---- help at all four levels ------------------------------------------------
630	
631	#[test]
632	fn root_help_succeeds_and_shows_only_root_surface() {
633	    let help = help_text(&["tool", "--help"]);
634	    for needle in [
635	        "--config",
636	        "<path>",
637	        "builtin.toml",
638	        "--define",
639	        "<key=value>",
640	        "serve",
641	        "check",
642	        "captured as a root plugin",
643	    ] {
644	        assert!(help.contains(needle), "root help missing {needle}:\n{help}");
645	    }
646	    for leaked in ["--port", "--tcp", "--udp", "--strict", "TRAILING", "worker"] {
647	        assert!(
648	            !help.contains(leaked),
649	            "root help unexpectedly contains {leaked}:\n{help}"
650	        );
651	    }
652	    assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
653	}
654	
655	#[test]
656	fn serve_help_succeeds_without_define_surface() {
657	    let help = help_text(&["tool", "serve", "--help"]);
658	    for needle in [
659	        "worker",
660	        "--config",
661	        "builtin.toml",
662	        "tool serve",
663	        "captured as a serve plugin",
664	    ] {
665	        assert!(help.contains(needle), "serve help missing {needle}:\n{help}");
666	    }
667	    // `--define` belongs to the root alone and must not leak downwards.
668	    for leaked in ["--define", "--port", "--tcp", "--udp", "--strict"] {
669	        assert!(
670	            !help.contains(leaked),
671	            "serve help unexpectedly contains {leaked}:\n{help}"
672	        );
673	    }
674	    assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
675	}
676	
677	#[test]
678	fn worker_help_succeeds_while_port_is_missing() {
679	    let help = help_text(&["tool", "serve", "worker", "--help"]);
680	    for needle in [
681	        "--port",
682	        "<port>",
683	        "--tcp",
684	        "--udp",
685	        "TRAILING",
686	        "--config",
687	        "builtin.toml",
688	        "tool serve worker",
689	    ] {
690	        assert!(help.contains(needle), "worker help missing {needle}:\n{help}");
691	    }
692	    for leaked in ["--define", "--strict", "root plugin", "serve plugin"] {
693	        assert!(
694	            !help.contains(leaked),
695	            "worker help unexpectedly contains {leaked}:\n{help}"
696	        );
697	    }
698	    assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
699	}
700	
701	#[test]
702	fn check_help_succeeds_without_path_and_shows_only_check_surface() {
703	    let help = help_text(&["tool", "check", "--help"]);
704	    for needle in ["--strict", "PATH", "--config", "builtin.toml", "tool check"] {
705	        assert!(help.contains(needle), "check help missing {needle}:\n{help}");
706	    }
707	    for leaked in [
708	        "--define",
709	        "--port",
710	        "--tcp",
711	        "--udp",
712	        "TRAILING",
713	        "worker",
714	        "root plugin",
715	        "serve plugin",
716	    ] {
717	        assert!(
718	            !help.contains(leaked),
719	            "check help unexpectedly contains {leaked}:\n{help}"
720	        );
721	    }
722	    assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
723	}
724	
725	#[test]
726	fn help_ordering_is_stable_across_repeated_requests() {
727	    for argv in [
728	        &["tool", "--help"][..],
729	        &["tool", "serve", "--help"][..],
730	        &["tool", "serve", "worker", "--help"][..],
731	        &["tool", "check", "--help"][..],
732	    ] {
733	        assert_eq!(
734	            help_text(argv),
735	            help_text(argv),
736	            "help rendering is not stable for {argv:?}"
737	        );
738	    }
739	}
740	
741	// ---- fixed-order isolation sequence -----------------------------------------
742	
743	#[test]
744	fn fixed_order_sequence_defines_ports_externals_worker_help_is_isolated() {
745	    // Clean baselines captured before anything else runs; the trailing help
746	    // requests must render byte-identical text after the intervening calls.
747	    let clean_root_help = help_text(&["tool", "--help"]);
748	    let clean_serve_help = help_text(&["tool", "serve", "--help"]);
749	    let clean_worker_help = help_text(&["tool", "serve", "worker", "--help"]);
750	    let clean_check_help = help_text(&["tool", "check", "--help"]);
751	
752	    // 1. Define success: strict pairs land in the structure in order.
753	    let (config, define, worker) = worker_ok(&[
754	        "tool",
755	        "--define",
756	        "a=1",
757	        "--define",
758	        "b=2",
759	        "serve",
760	        "worker",
761	        "--port",
762	        "8080",
763	        "--tcp",
764	    ]);
765	    assert_eq!(config, "builtin.toml");
766	    assert_eq!(
767	        define,
768	        vec![("a".to_owned(), "1".to_owned()), ("b".to_owned(), "2".to_owned())]
769	    );
770	    assert_eq!(worker.port, 8080);
771	    assert!(worker.tcp);
772	
773	    // 2. Every invalid-define class fails on its own token.
774	    for raw in INVALID_DEFINES {
775	        let argv = ["tool", "--define", raw, "check"];
776	        let (kind, msg) = fail_kind(&argv);
777	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
778	        assert!(msg.contains("--define"), "{argv:?}: {msg}");
779	    }
780	
781	    // 3. Port negatives: invalid values, never coerced.
782	    for bad in ["", "-1", "+80", "0x10", "1_000", " 80", "0", "65536"] {
783	        let argv = ["tool", "serve", "worker", &format!("--port={bad}")];
784	        let (kind, msg) = fail_kind(&argv);
785	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
786	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
787	    }
788	
789	    // 4. External command success in a fresh parse: no define or port state
790	    //    leaks from the failing calls, and plugin tokens stay verbatim.
791	    let (config, define, tokens) = root_external_ok(&[
792	        "tool", "--define", "k=v", "plug", "--define", "=v", "--port", "0",
793	    ]);
794	    assert_eq!(config, "builtin.toml");
795	    assert_eq!(define, vec![("k".to_owned(), "v".to_owned())]);
796	    assert_eq!(tokens, vec!["plug", "--define", "=v", "--port", "0"]);
797	
798	    // 5. A valid worker parse after the failures sees only its own input.
799	    let (config, define, worker) = worker_ok(&[
800	        "tool", "serve", "worker", "--port", "9090", "--udp", "--", "z", "--define",
801	    ]);
802	    assert_eq!(config, "builtin.toml");
803	    assert_eq!(define, Vec::<(String, String)>::new());
804	    assert_eq!(
805	        worker,
806	        WorkerArgs {
807	            port: 9090,
808	            tcp: false,
809	            udp: true,
810	            trailing: vec!["z".to_owned(), "--define".to_owned()],
811	        }
812	    );
813	
814	    // 6. Every help request still succeeds while required values are missing,
815	    //    is identical to the clean baselines, and carries no stale error.
816	    for (argv, clean) in [
817	        (&["tool", "--help"][..], &clean_root_help),
818	        (&["tool", "serve", "--help"][..], &clean_serve_help),
819	        (&["tool", "serve", "worker", "--help"][..], &clean_worker_help),
820	        (&["tool", "check", "--help"][..], &clean_check_help),
821	    ] {
822	        let help = help_text(argv);
823	        assert_eq!(&help, clean, "{argv:?} help changed across the sequence");
824	        assert!(!help.contains("novalue"), "{argv:?}:\n{help}");
825	        assert!(!help.contains("0x10"), "{argv:?}:\n{help}");
826	    }
827	}
