165	#[test]
166	fn help_and_version_like_tokens_after_name_are_data() {
167	    let (_, _, tokens) = external_ok(&["tool", "plug", "--help", "--version", "-h"]);
168	    assert_eq!(tokens, vec!["plug", "--help", "--version", "-h"]);
169	}
170	
171	#[test]
172	fn root_options_after_external_name_are_captured_not_stolen() {
173	    let (config, define, tokens) = external_ok(&[
174	        "tool",
175	        "--config",
176	        "custom.toml",
177	        "plug",
178	        "--config",
179	        "stolen.toml",
