use clap::{Arg, ArgAction, ArgMatches, Command};

fn parse_port(raw: &str) -> Result<u16, String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("invalid port `{raw}`"));
    }
    match raw.parse::<u32>() {
        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
        _ => Err(format!("invalid port `{raw}`")),
    }
}

fn parse_define(raw: &str) -> Result<(String, String), String> {
    let Some((key, value)) = raw.split_once('=') else {
        return Err(format!("invalid define `{raw}`"));
    };
    if value.contains('=') || key.is_empty() || value.is_empty() {
        return Err(format!("invalid define `{raw}`"));
    }
    Ok((key.to_owned(), value.to_owned()))
}

fn cli() -> Command {
    Command::new("tool")
        .subcommand_required(true)
        .after_help("External plugins: any other <COMMAND> is captured as a root plugin.")
        .arg(
            Arg::new("config")
                .long("config")
                .global(true)
                .default_value("builtin.toml")
                .value_name("path"),
        )
        .arg(
            Arg::new("define")
                .long("define")
                .value_name("key=value")
                .action(ArgAction::Append)
                .value_parser(parse_define),
        )
        .subcommand(
            Command::new("serve")
                .after_help(
                    "External plugins: any other <COMMAND> is captured as a serve plugin.",
                )
                .allow_external_subcommands(true)
                .subcommand(
                    Command::new("worker")
                        .arg(
                            Arg::new("port")
                                .long("port")
                                .value_name("port")
                                .required(true)
                                .value_parser(parse_port),
                        )
                        .arg(Arg::new("http").long("http").action(ArgAction::SetTrue).conflicts_with("https"))
                        .arg(Arg::new("https").long("https").action(ArgAction::SetTrue).conflicts_with("http"))
                        .arg(
                            Arg::new("trailing")
                                .num_args(1..)
                                .action(ArgAction::Append)
                                .last(true),
                        ),
                ),
        )
        .subcommand(
            Command::new("check")
                .arg(Arg::new("path"))
                .arg(Arg::new("strict").long("strict").action(ArgAction::SetTrue)),
        )
        .allow_external_subcommands(true)
}

fn dump(argv: &[&str]) {
    match cli().try_get_matches_from(argv) {
        Ok(m) => {
            let cfg = m.get_one::<String>("config");
            println!("OK argv={argv:?} root config={cfg:?} sub={:?}", m.subcommand().map(|(n, _)| n));
            if let Some((name, sub)) = m.subcommand() {
                println!("  sub[{name}] config={:?}", sub.get_one::<String>("config"));
                if let Some((n2, s2)) = sub.subcommand() {
                    println!("  subsub[{n2}] config={:?} port={:?} http={} https={} trailing={:?}",
                        s2.get_one::<String>("config"),
                        s2.get_one::<u16>("port"),
                        s2.get_flag("http"),
                        s2.get_flag("https"),
                        s2.get_many::<String>("trailing").map(|v| v.cloned().collect::<Vec<_>>()).unwrap_or_default(),
                    );
                    let toks = s2.get_many::<String>("").map(|v| v.cloned().collect::<Vec<_>>()).unwrap_or_default();
                    println!("  ext tokens={toks:?}");
                }
                let toks = sub.get_many::<String>("").map(|v| v.cloned().collect::<Vec<_>>()).unwrap_or_default();
                if !toks.is_empty() {
                    println!("  serve-ext tokens={toks:?}");
                }
            }
        }
        Err(e) => println!("ERR argv={argv:?} kind={:?}\n{e}", e.kind()),
    }
}

#[test]
fn scratch() {
    for argv in [
        &["tool", "--define", "a=1", "serve", "worker", "--port", "8080", "--http"][..],
        &["tool", "serve", "worker", "--port", "9090", "--", "z", "--define"][..],
        &["tool", "serve", "--define", "a=1", "plug"][..],
        &["tool", "serve", "worker", "--port", "80", "--port", "90"][..],
        &["tool", "serve", "worker", "--port", "80", "--http", "--https"][..],
        &["tool", "serve", "worker", "--port", "-1"][..],
        &["tool", "check", "65536"][..],
        &["tool", "check", "--port", "80"][..],
        &["tool", "plug", "--port", "0"][..],
        &["tool", "serve", "plug", "--port", "abc"][..],
        &["tool", "serve", "worker", "--port", "80", "--config", "a", "--config", "b"][..],
        &["tool", "--define"][..],
        &["tool", "--define", "--config", "c.toml", "check"][..],
        &["tool", "--define", "=v", "check"][..],
        &["tool", "--", "plug", "x"][..],
    ] {
        dump(argv);
    }
    let _ = ArgMatches::default;
}

