use clap::{Arg, ArgAction, Command};

fn parse_port(raw: &str) -> Result<u16, String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("invalid port `{raw}`: expected a decimal number between 1 and 65535"));
    }
    match raw.parse::<u32>() {
        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
        _ => Err(format!("invalid port `{raw}`: expected a decimal number between 1 and 65535")),
    }
}

fn parse_define(raw: &str) -> Result<(String, String), String> {
    let Some((key, value)) = raw.split_once('=') else {
        return Err(format!("invalid define `{raw}`: expected key=value"));
    };
    if value.contains('=') {
        return Err(format!("invalid define `{raw}`: expected exactly one `=` in key=value"));
    }
    if key.is_empty() {
        return Err(format!("invalid define `{raw}`: key must not be empty"));
    }
