#[test]
fn external_captures_keep_every_token_after_the_name_verbatim() {
    let (config, define, tokens) = root_external_ok(&[
        "tool",
        "--define",
        "a=1",
        "--config",
        "custom.toml",
        "plug",
        "--config",
        "stolen.toml",
        "--define",
        "=v",
        "serve",
        "worker",
